CREATE TABLE IF NOT EXISTS profiles (id SERIAL PRIMARY KEY, clerk_user_id TEXT NOT NULL UNIQUE, role TEXT NOT NULL DEFAULT 'buyer', display_name TEXT, email TEXT, logo_url TEXT, banner_url TEXT, phone TEXT, city TEXT, address TEXT, business_description TEXT, is_verified BOOLEAN NOT NULL DEFAULT false, is_suspended BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS categories (id SERIAL PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS trees (id SERIAL PRIMARY KEY, slug TEXT NOT NULL UNIQUE, common_name TEXT NOT NULL, scientific_name TEXT NOT NULL, family TEXT, native_region TEXT, description TEXT, climate TEXT, soil TEXT, water_requirement TEXT, sunlight TEXT, growth_rate TEXT, height TEXT, lifespan TEXT, flowering_season TEXT, fruiting_season TEXT, uses TEXT, hero_image_url TEXT, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tree_categories (tree_id INTEGER NOT NULL REFERENCES trees(id) ON DELETE CASCADE, category_id INTEGER NOT NULL REFERENCES categories(id) ON DELETE CASCADE, PRIMARY KEY (tree_id, category_id));
CREATE TABLE IF NOT EXISTS tree_varieties (id SERIAL PRIMARY KEY, tree_id INTEGER NOT NULL REFERENCES trees(id) ON DELETE CASCADE, variety_name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, description TEXT, origin TEXT, taste TEXT, fruit_size TEXT, tree_size TEXT, yield_amount TEXT, disease_resistance TEXT, harvest_time TEXT, best_climate TEXT, advantages TEXT, disadvantages TEXT, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tree_images (id SERIAL PRIMARY KEY, tree_id INTEGER REFERENCES trees(id) ON DELETE CASCADE, variety_id INTEGER REFERENCES tree_varieties(id) ON DELETE CASCADE, image_url TEXT NOT NULL, image_type TEXT NOT NULL DEFAULT 'general', sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS listings (id SERIAL PRIMARY KEY, seller_id INTEGER NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, variety_id INTEGER NOT NULL REFERENCES tree_varieties(id) ON DELETE CASCADE, price NUMERIC(12,2) NOT NULL, currency TEXT NOT NULL DEFAULT 'BDT', quantity INTEGER NOT NULL, unit TEXT NOT NULL DEFAULT 'per plant', location TEXT, delivery_available BOOLEAN NOT NULL DEFAULT false, delivery_notes TEXT, status TEXT NOT NULL DEFAULT 'pending', rejection_reason TEXT, images JSON NOT NULL DEFAULT '[]', view_count INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS cart_items (id SERIAL PRIMARY KEY, buyer_id INTEGER NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, listing_id INTEGER NOT NULL REFERENCES listings(id) ON DELETE CASCADE, quantity INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS orders (id SERIAL PRIMARY KEY, buyer_id INTEGER NOT NULL REFERENCES profiles(id), seller_id INTEGER NOT NULL REFERENCES profiles(id), listing_id INTEGER NOT NULL REFERENCES listings(id), quantity INTEGER NOT NULL, total_price NUMERIC(12,2) NOT NULL, currency TEXT NOT NULL DEFAULT 'BDT', status TEXT NOT NULL DEFAULT 'pending_payment', payment_status TEXT NOT NULL DEFAULT 'pending', created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payments (id SERIAL PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), bkash_payment_id TEXT, bkash_trx_id TEXT, amount NUMERIC(12,2) NOT NULL, status TEXT NOT NULL DEFAULT 'pending', pending_cart_item_ids JSON DEFAULT '[]', created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS reviews (id SERIAL PRIMARY KEY, reviewer_id INTEGER NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, target_type TEXT NOT NULL, target_id INTEGER NOT NULL, rating INTEGER NOT NULL, comment TEXT, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS wishlist_items (id SERIAL PRIMARY KEY, buyer_id INTEGER NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, listing_id INTEGER NOT NULL REFERENCES listings(id) ON DELETE CASCADE, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS variety_requests (id SERIAL PRIMARY KEY, seller_id INTEGER NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, tree_id INTEGER NOT NULL, requested_variety_name TEXT NOT NULL, notes TEXT, status TEXT NOT NULL DEFAULT 'pending', rejection_reason TEXT, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS courier_integrations (id SERIAL PRIMARY KEY, seller_id INTEGER NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, courier_name TEXT NOT NULL, api_key_encrypted TEXT NOT NULL, api_secret_encrypted TEXT, merchant_id TEXT, is_active BOOLEAN NOT NULL DEFAULT true, is_default BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS shipments (id SERIAL PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), seller_id INTEGER NOT NULL REFERENCES profiles(id), courier_integration_id INTEGER REFERENCES courier_integrations(id), courier_tracking_id TEXT, status TEXT NOT NULL DEFAULT 'pending', last_updated TIMESTAMP, tracking_url TEXT);
CREATE TABLE IF NOT EXISTS app_settings (id SERIAL PRIMARY KEY, key TEXT NOT NULL UNIQUE, value TEXT, is_secret BOOLEAN NOT NULL DEFAULT false, description TEXT, updated_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS pending_payments (id SERIAL PRIMARY KEY, buyer_id INTEGER NOT NULL REFERENCES profiles(id), bkash_payment_id TEXT NOT NULL UNIQUE, cart_item_ids JSON NOT NULL DEFAULT '[]', total_amount NUMERIC(12,2) NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TIMESTAMP NOT NULL DEFAULT NOW());
